generate.initial_sparql:
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?category
       (AVG(xsd:decimal(?holdingGain)) AS ?avgHoldingGain)
       (AVG(xsd:decimal(?allocConcentration)) AS ?avgAllocationConcentration)
       (AVG(xsd:decimal(?rebalanceGap)) AS ?avgRebalancingGap)
       (AVG(xsd:decimal(?scenarioChange)) AS ?avgScenarioChange)
       (AVG(xsd:decimal(?goalVolatility)) AS ?avgGoalVolatility)
WHERE {
  ?inv a wm:Investor ;
       wm:investorId ?invId ;
       wm:category ?category .

  OPTIONAL {
    SELECT ?invId (AVG(xsd:decimal(?returnsPct)) AS ?holdingGain) WHERE {
      ?holding a wm:PortfolioHolding ;
               wm:investorId ?invId ;
               wm:returnsPct ?returnsPct .
    } GROUP BY ?invId
  }

  OPTIONAL {
    SELECT ?invId (AVG(xsd:decimal(?allocationPct)) AS ?allocConcentration) WHERE {
      ?alloc a wm:SectorAllocation ;
             wm:investorId ?invId ;
             wm:allocationPct ?allocationPct .
    } GROUP BY ?invId
  }

  OPTIONAL {
    SELECT ?invId (AVG(xsd:decimal(?gap)) AS ?rebalanceGap) WHERE {
      ?reb a wm:RebalancingAction ;
           wm:investorId ?invId ;
           wm:targetAllocationPct ?target ;
           wm:currentAllocationPct ?current .
      BIND((xsd:decimal(?target) - xsd:decimal(?current)) AS ?gap)
    } GROUP BY ?invId
  }

  OPTIONAL {
    SELECT ?invId (AVG(xsd:decimal(?change)) AS ?scenarioChange) WHERE {
      ?scen a wm:ScenarioRebalancing ;
            wm:investorId ?invId ;
            wm:newAllocationPct ?new ;
            wm:currentAllocationPct ?curr .
      BIND((xsd:decimal(?new) - xsd:decimal(?curr)) AS ?change)
    } GROUP BY ?invId
  }

  OPTIONAL {
    SELECT ?invId (AVG(xsd:decimal(?volatility)) AS ?goalVolatility) WHERE {
      ?goal a wm:InvestmentGoal ;
            wm:investorId ?invId ;
            wm:avgVolatilityPct ?volatility .
    } GROUP BY ?invId
  }
}
GROUP BY ?category

